import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  Input,
  Renderer2,
  ViewEncapsulation,
  inject,
  DOCUMENT,
} from '@angular/core';
import { QIconRegistryService } from './icon-registry.service';
import { QIconSize } from './types/icon-size.type';

const SIZE_CLASS_MAP = {
  '12': 'q-icon--xxs',
  '16': 'q-icon--xs',
  '20': 'q-icon--sm',
  '24': 'q-icon--md',
  '40': 'q-icon--lg',
  '48': 'q-icon--xl',
  '56': 'q-icon--56',
  '80': 'q-icon--80',
  '128': 'q-icon--128',
  '400': 'q-icon--400',
  'w-86': 'q-icon-logo--xs',
  'w-103': 'q-icon-logo--s',
  'w-120': 'q-icon-logo--m',
};

/** @dynamic */
@Component({
  selector: 'q-icon',
  template: `<ng-content />`,
  styleUrls: ['./icon.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QIconComponent {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-icon';

  @Input() @HostBinding('attr.name') get name(): string {
    return this._name;
  }
  set name(iconName: string) {
    if (iconName) {
      this._name = iconName;
      this._updateSvgIcon(iconName);
      this._size && this._updateSize(this._size);
    }
  }

  @Input() get size(): QIconSize {
    return this._size;
  }
  set size(size: QIconSize) {
    size && this._updateSize(size);
    this._size = size;
  }

  /** @hidden */
  @HostBinding('class') hostClass = 'q-icon';
  @HostBinding('class.q-icon-flag') get isFlag(): boolean {
    return this.name.startsWith('flag');
  }

  private _name = '';
  private _size!: QIconSize;
  private _svgIcon: SVGElement | null = null;
  private readonly _elementRef = inject(ElementRef);
  private readonly _renderer2 = inject(Renderer2);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _document = inject(DOCUMENT);

  private _svgElementFromString(svgContent: string | null): SVGElement | null {
    const div = this._document.createElement('DIV');
    div.innerHTML = svgContent ?? '';

    return (
      div.querySelector('svg') ||
      this._document.createElementNS('http://www.w3.org/2000/svg', 'path')
    );
  }

  private _updateSvgIcon(iconName: string): void {
    if (this._svgIcon) {
      this._renderer2.removeChild(this._elementRef.nativeElement, this._svgIcon);
    }

    const svgData = this._iconRegistry.getIcon(iconName) || null;
    this._svgIcon = this._svgElementFromString(svgData);
    if (this._svgIcon) {
      this._renderer2.appendChild(this._elementRef.nativeElement, this._svgIcon);
    }
  }

  private _updateSize(size: QIconSize): void {
    if (this._size) {
      this._renderer2.removeClass(this._elementRef.nativeElement, SIZE_CLASS_MAP[this._size]);
    }

    this._renderer2.addClass(this._elementRef.nativeElement, SIZE_CLASS_MAP[size]);
  }
}
