import { Injectable } from '@angular/core';
import { QIcon } from '@questrade/allspark-icons';

@Injectable({
  providedIn: 'root',
})
export class QIconRegistryService {
  private readonly _registry = new Map<string, string>();

  registerIcon(icon: QIcon): void {
    this._registry.set(icon.name, icon.data);
  }

  registerIcons(icons: QIcon[]): void {
    icons.forEach((icon: QIcon) => this.registerIcon(icon));
  }

  hasIcon(iconName: string): boolean {
    return this._registry.has(iconName);
  }

  getIcon(iconName: string): string {
    if (!this._registry.has(iconName)) {
      console.warn(
        `We couldn't find the icon with the name '${iconName}', did you add it to the Icon registry?`,
      );
      return '';
    }

    return this._registry.get(iconName) || '';
  }
}
